export function isWhiteSilverRumProduct(product: {
  sku?: string;
  name?: string;
  subCategory?: string;
}): boolean {
  const sku = (product.sku || '').toUpperCase();
  const name = (product.name || '').toLowerCase();
  const sub = (product.subCategory || '').toLowerCase();
  if (sub === 'white rum') return true;
  if (sku.includes('-RUM-WHT-')) return true;
  if (
    sub.includes('rum') &&
    (name.includes('carta blanca') ||
      name.includes('white rum') ||
      name.includes('white spiced') ||
      name.includes('3 years cuban white'))
  ) {
    return true;
  }
  return false;
}

export function isCreamLiqueurProduct(product: {
  sku?: string;
  name?: string;
  brand?: string;
  subCategory?: string;
  isCreamBased?: boolean;
}): boolean {
  if (product.isCreamBased) return true;
  const sku = (product.sku || '').toUpperCase();
  const text = `${product.name || ''} ${product.brand || ''} ${product.subCategory || ''}`.toLowerCase();
  if (sku.includes('-LIQ-CRM-') || (product.subCategory || '').toLowerCase() === 'cream liqueur') {
    return true;
  }
  if (
    text.includes('baileys') ||
    text.includes('amarula') ||
    text.includes('sheridan') ||
    text.includes('tequila rose') ||
    text.includes('strawberry lips') ||
    text.includes('best marula') ||
    text.includes('cream liqueur') ||
    text.includes('irish cream')
  ) {
    return true;
  }
  return false;
}

const ENRICHED_PRE_PIPELINE_PRODUCTS: Product[] = mergeAttachedCatalogueWithExistingProducts(
  RAW_NAIROBI_DRINKS_PRODUCTS
).map(product => {
  const isRum =
    product.subCategory === 'Rum' ||
    product.subCategory === 'White Rum' ||
    product.subCategory === 'Spiced & Dark Rum' ||
    product.sku.includes('-RUM-');

  const isCream = isCreamLiqueurProduct(product);

  const resolvedSubCategory = isRum
    ? isWhiteSilverRumProduct(product)
      ? 'White Rum'
      : 'Spiced & Dark Rum'
    : isCream
    ? 'Cream Liqueur'
    : product.subCategory;

  const enriched: Product = {
    ...product,
    subCategory: resolvedSubCategory,
    ...(isCream
      ? {
          isCreamBased: true,
          requiresBatchExpiryTracking: true,
          recommendedShelfLifeMonths: product.recommendedShelfLifeMonths || 24,
          maxStorageTempCelsius: product.maxStorageTempCelsius || 25,
          manufactureDate: product.manufactureDate || '2025-10-15',
          defaultExpiryDate: product.defaultExpiryDate || '2027-10-15'
        }
      : {})
  };

  return {
    ...enriched,
    image: enriched.image || getProductImageUrl(enriched)
  };
});

export const CATALOG_BARCODE_QUALITY_AUDIT = executeCatalogBarcodeQualityPipeline(
  ENRICHED_PRE_PIPELINE_PRODUCTS
);

export const NAIROBI_DRINKS_PRODUCTS: Product[] = CATALOG_BARCODE_QUALITY_AUDIT.products;

/**
 * Returns empty initial inventory until real branches/distributors are created by the user.
 */
export function buildInitialNairobiDrinksInventory(_products: Product[]): InventoryItem[] {
  return [];
}
